Office.onReady(() => {
  const item = Office.context.mailbox.item;

  const fill = (id, value) => (document.getElementById(id).value = value);

  if (typeof item.subject === "string") {
    // Read mode: plain properties
    fill("name", item.subject);
    fill("start", item.start);
    fill("end", item.end);
  } else {
    // Compose mode: async getters
    item.subject.getAsync(r => fill("name", r.value));
    item.start.getAsync(r => fill("start", r.value));
    item.end.getAsync(r => fill("end", r.value));
  }

  document.getElementById("open").onclick = () => {
    window.open("https://projects.zoho.in/", "_blank"); // use your portal URL/data center
  };
});